function validate([preorder]) {
  if (preorder.length < 1 || preorder.length > 10000) return 'preorder needs 1 to 10,000 values.';
  if (preorder.some(v => v < 1 || v > 10000)) return 'Each value is between 1 and 10,000.';
  if (new Set(preorder).size !== preorder.length) return 'The values must be distinct.';
  return null;
}

