  const stack = [];
  let lower = -Infinity;

  for (const value of preorder) {
    if (value < lower) {
      return false;
    }
    while (stack.length > 0 && stack[stack.length - 1] < value) {
      lower = stack.pop();
    }
    stack.push(value);
  }
  return true;
}

