function verifyPreorder(preorder) {
  // Insert the values in the given order; a valid preorder rebuilds a tree whose own preorder is the same list.
  const root = { val: preorder[0], left: null, right: null };
  for (let i = 1; i < preorder.length; i++) {
    let node = root;
    for (;;) {
      const side = preorder[i] < node.val ? 'left' : 'right';
      if (node[side] === null) { node[side] = { val: preorder[i], left: null, right: null }; break; }
      node = node[side];
    }
  }
  const walk = [], pending = [root];
  while (pending.length) {
    const node = pending.pop();
    walk.push(node.val);
    if (node.right) pending.push(node.right);
    if (node.left) pending.push(node.left);
  }
  return walk.every((v, i) => v === preorder[i]);
}

