function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 7);
  const pool = Array.from({ length: large ? 10000 : 12 }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const values = pool.slice(0, n);
  // A random order is usually not a preorder; otherwise build a BST from it and emit its real preorder.
  if (rand() < 0.4) return [values];
  const left = new Map(), right = new Map();
  for (const v of values.slice(1)) {
    let node = values[0];
    for (;;) {
      const side = v < node ? left : right;
      if (!side.has(node)) { side.set(node, v); break; }
      node = side.get(node);
    }
  }
  const order = [], stack = [values[0]];
  while (stack.length) {
    const node = stack.pop();
    order.push(node);
    if (right.has(node)) stack.push(right.get(node));
    if (left.has(node)) stack.push(left.get(node));
  }
  // Sometimes swap two neighbours, which may or may not break the order.
  if (n > 1 && rand() < 0.3) {
    const k = Math.floor(rand() * (n - 1));
    [order[k], order[k + 1]] = [order[k + 1], order[k]];
  }
  return [order];
}
